/// 编辑保存（content/importance/kind；tags 与 source 不可改）。
/// content 变更时重算嵌入（持锁前算）。嵌入引擎不可用时拒绝保存（防语义静默丢失）。
#[tauri::command]
pub async fn mem_update(
    app: AppHandle,
    id: String,
    content: String,
    importance: i64,
    kind: String,
) -> CommandResult<MemItemView> {
    let r = tauri::async_runtime::spawn_blocking(move || -> Result<MemItemView, String> {
        let trimmed = content.trim();
        if trimmed.is_empty() {
            return Err("记忆内容不能为空（要删除请用删除按钮）".into());
        }
        let emb = embed::embed_text(trimmed);
        // 引擎不可用 → 拒写，避免编辑后语义检索静默失效（store::update_by_id
        // 的 CASE 会把 embedding 置 NULL，前端无从感知）
        if emb.is_none() && embed::engine_status().is_err() {
            match embed::engine_status() {
                Err(e) => return Err(format!("嵌入引擎不可用，编辑未保存：{e}")),
                Ok(()) => {} // 引擎 OK 但本条内容（截断/空/超长等）确实无向量 → 走旧路径
            }
        }
        let _g = lock_db();
        let conn = crate::db::open_db(&app).map_err(|e| e.to_string())?;
        update_core(
            &conn,
            &id,
            &content,
            importance,
            &kind,
            emb.as_deref(),
            now_ms(),
        )
    })

