use crate::error::CommandError;

pub(crate) fn update_core(
    conn: &rusqlite::Connection,
    id: &str,
    content: &str,
    importance: i64,
    kind: &str,
    embedding: Option<&[f32]>,
    now_ms: i64,
) -> Result<MemItemView, CommandError> {
    store::ensure_table(conn)?;
    let content = content.trim();
    if content.is_empty() {
        return Err(CommandError::InvalidArgument {
            field: "content".into(),
            value: content.to_string(),
            reason: "内容不能为空（要删除请用删除按钮）".into(),
        });
    }
    if content.chars().count() > MAX_CONTENT_CHARS {
        return Err(CommandError::InvalidArgument {
            field: "content".into(),
            value: format!("{} chars", content.chars().count()),
            reason: format!("记忆内容太长（≤{MAX_CONTENT_CHARS} 字）"),
        });
    }
    if !EDITABLE_KINDS.contains(&kind) {
        return Err(CommandError::InvalidArgument {
            field: "kind".into(),
            value: kind.into(),
            reason: "未知记忆类型".into(),
        });
    }
    let existing = store::find_by_id(conn, id)?
        .ok_or_else(|| CommandError::TaskNotFound(id.to_string()))?;

