/// 删除单条（显式用户操作允许删任何条目，含 evo: 前缀的自进化教训——
/// 前端 confirm 文案负责提示影响）。返回是否真删到。
/// 若条目受保护（is_protected=true），强制删除须经 `force=true`；
/// 受保护条目的删除须记录审计日志（kind/source/importance/now）。
pub(crate) fn delete_core(
    conn: &rusqlite::Connection,
    id: &str,
    force: bool,
) -> Result<bool, CommandError> {
    store::ensure_table(conn)?;
    let victim = store::find_by_id(conn, id)?
        .ok_or_else(|| CommandError::TaskNotFound(id.to_string()))?;
    if store::is_protected(&victim) && !force {
        return Err(CommandError::DomainRule {
            domain: "memory.delete_protected".into(),
            reason: format!("条目受保护（importance=5, source={}），需 force=true", victim.source),
        });
    }
    let deleted = store::delete_by_ids(conn, &[id.to_string()])? > 0;
    if deleted {
        eprintln!(
            "[audit] memory_panel_delete id={id} kind={} source={} importance={} protected={}",
            victim.kind, victim.source, victim.importance, !force
        );
    }
    Ok(deleted)
}

