Debounced search has a race: if `mem_list` for query A is still in flight when query B's debounce fires, A's response can resolve after B's and overwrite the fresher list. Track an in-flight token (a ref incremented each call) and discard stale resolutions.

```suggestion
  const reqIdRef = useRef(0);
  const reload = useCallback(async (q: string, kind: string) => {
    const reqId = ++reqIdRef.current;
    try {
      const [listRes, stRes] = await Promise.allSettled([
        invoke<MemItemView[]>("mem_list", {
          query: q || null,
          kind: kind === "all" ? null : kind,
        }),
        invoke<MemStats | null>("mem_stats"),
      ]);
      if (reqId !== reqIdRef.current) return; // stale, newer request superseded
      if (listRes.status === "fulfilled") {
        setItems(Array.isArray(listRes.value) ? listRes.value : []);
        setLoadError("");
      } else {
        setLoadError(formatCommandError(listRes.reason));
      }
      if (stRes.status === "fulfilled") {
        const st = stRes.value;
        if (st && typeof st === "object" && "total" in st) setStats(st);
      }
    } catch (e) {
      if (reqId !== reqIdRef.current) return;
      setLoadError(formatCommandError(e));
    }
  }, []);
